INSERT INTO listings (id,data,status,version) VALUES ('amazon-alexa-ai','{"id":"amazon-alexa-ai","company":"Amazon","initial":"a","title":"Software Dev Engineer, Alexa AI","location":"Bengaluru, India","region":"India","category":"Private","experience":"2+ years","remote":false,"level":"Experienced","tags":["Engineering","Artificial intelligence"],"salary":"Not disclosed","deadline":"Not specified","checked":"2026-10-18","url":"https://amazon.jobs/en-gb/jobs/10568545/software-dev-engineer-alexa-ai","summary":"Build software supporting Alexa’s AI services, with a focus on scalable applications and distributed systems.","requirements":["At least two years of professional software development experience, excluding internships.","Programming experience in at least one language.","A computer science degree or equivalent is preferred."],"details":"The work involves collaborating with engineering teams, designing services and delivering software in an agile environment. Read the employer’s full description before applying.","note":"The employer page displayed an application link when reviewed. No closing date or salary was stated.","status":"published","version":1,"sourceType":"Employer","education":"See eligibility below","batch":"Not specified","fees":"Not specified","selection":"Not specified by the employer","howToApply":"Open the recruitment page, read the current requirements, and follow the employer’s application process.","publishedAt":"2026-10-18","updatedAt":"2026-10-18"}'::jsonb,'published',1) ON CONFLICT (id) DO NOTHING;
